pid='r08_c11_p33';ver='v04';old=R/'guides/r08_c11_p33.native-context-v03.png';target=R/f'guides/{pid}.native-context-{ver}.png';assert not target.exists();shutil.copyfile(old,target);g=rd(Path(str(old)+'.generation.json'))
